@@ -2,6 +2,10 @@ package org.jsoup.select;

 import org.jsoup.nodes.Element;
 import org.jsoup.nodes.Node;
+import org.jsoup.nodes.TextNode;
+import org.jsoup.nodes.PseudoTextElement;
+
+import java.util.ArrayList;

 import static org.jsoup.select.NodeFilter.FilterResult.CONTINUE;
 import static org.jsoup.select.NodeFilter.FilterResult.STOP;
@@ -24,10 +28,25 @@ public class Collector {
      */
     public static Elements collect (Evaluator eval, Element root) {
         Elements elements = new Elements();
-        NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        if (containsMatchText(eval)) {
+            NodeTraversor.traverse(new TextAccumulator(root, elements, eval), root);
+        } else {
+            NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        }
         return elements;
     }

+    private static boolean containsMatchText(Evaluator eval) {
+        if (eval instanceof Evaluator.MatchText) {
+            return true;
+        }
+        if (eval instanceof CombiningEvaluator) {
+            CombiningEvaluator combining = (CombiningEvaluator) eval;
+            return combining.containsMatchText();
+        }
+        return false;
+    }
+
     private static class Accumulator implements NodeVisitor {
         private final Element root;
         private final Elements elements;
@@ -52,6 +71,85 @@ public class Collector {
         }
     }

+    private static class TextAccumulator implements NodeVisitor {
+        private final Element root;
+        private final Elements elements;
+        private final Evaluator eval;
+
+        TextAccumulator(Element root, Elements elements, Evaluator eval) {
+            this.root = root;
+            this.elements = elements;
+            this.eval = eval;
+        }
+
+        public void head(Node node, int depth) {
+            if (node instanceof Element) {
+                Element el = (Element) node;
+                // Check if element matches (using MatchText-aware matching)
+                if (matchesWithoutMatchText(el)) {
+                    // Extract text nodes from this element
+                    for (Node child : el.childNodes()) {
+                        if (child instanceof TextNode) {
+                            TextNode textNode = (TextNode) child;
+                            String text = textNode.getWholeText().trim();
+                            if (text.length() > 0) {
+                                PseudoTextElement pseudo = new PseudoTextElement(textNode);
+                                elements.add(pseudo);
+                            }
+                        }
+                    }
+                }
+            }
+        }
+
+        private boolean matchesWithoutMatchText(Element el) {
+            // Create an evaluator without the MatchText part
+            Evaluator modified = removeMatchText(eval);
+            return modified.matches(root, el);
+        }
+
+        private Evaluator removeMatchText(Evaluator eval) {
+            if (eval instanceof Evaluator.MatchText) {
+                return new Evaluator.AllElements(); // Match all elements
+            }
+            if (eval instanceof CombiningEvaluator.And) {
+                CombiningEvaluator.And and = (CombiningEvaluator.And) eval;
+                ArrayList<Evaluator> filtered = new ArrayList<>();
+                for (Evaluator e : and.evaluators) {
+                    if (!(e instanceof Evaluator.MatchText)) {
+                        filtered.add(removeMatchText(e));
+                    }
+                }
+                if (filtered.size() == 0) {
+                    return new Evaluator.AllElements();
+                } else if (filtered.size() == 1) {
+                    return filtered.get(0);
+                } else {
+                    return new CombiningEvaluator.And(filtered);
+                }
+            }
+            if (eval instanceof CombiningEvaluator.Or) {
+                CombiningEvaluator.Or or = (CombiningEvaluator.Or) eval;
+                ArrayList<Evaluator> filtered = new ArrayList<>();
+                for (Evaluator e : or.evaluators) {
+                    filtered.add(removeMatchText(e));
+                }
+                if (filtered.size() == 0) {
+                    return new Evaluator.AllElements();
+                } else if (filtered.size() == 1) {
+                    return filtered.get(0);
+                } else {
+                    return new CombiningEvaluator.Or(filtered);
+                }
+            }
+            return eval;
+        }
+
+        public void tail(Node node, int depth) {
+            // void
+        }
+    }
+
     public static Element findFirst(Evaluator eval, Element root) {
         FirstFinder finder = new FirstFinder(root, eval);
         NodeTraversor.filter(finder, root);
